mapper.select:
select
a.preset_id,
a.camera_id,
a.preset_num,
a.preset_name,
a.creator_user,
a.creator_time,
a.is_use,
a.preset_img,
a.inspection_postion,
a.collect_status,
a.calibration_status
from t_camera_preset a
where 1 = 1
 and a.preset_id = #{presetId, jdbcType=BIGINT}
 and a.camera_id = #{cameraId, jdbcType=BIGINT}
 and a.preset_num = #{presetNum, jdbcType=INTEGER}
 and a.preset_name like concat('%',#{presetName, jdbcType=VARCHAR},'%')
 and a.creator_user = #{creatorUser, jdbcType=VARCHAR}
 and a.creator_time = #{creatorTime, jdbcType=TIMESTAMP}
 and a.is_use = #{isUse, jdbcType=INTEGER}
 and a.preset_img = #{presetImg, jdbcType=VARCHAR}
 and a.inspection_postion = #{inspectionPostion, jdbcType=INTEGER}
 and a.collect_status = #{collectStatus, jdbcType=INTEGER}
 and a.calibration_status = #{calibrationStatus, jdbcType=INTEGER}

select
a.preset_id,
a.camera_id,
b.camera_name,
a.preset_num,
a.preset_name,
a.creator_user,
a.creator_time,
a.is_use,
a.preset_img,
a.inspection_postion,
a.collect_status,
a.calibration_status,
a.remark
from t_camera_preset a,t_camera_info b
where 1 = 1
 and a.preset_id = #{presetId, jdbcType=BIGINT}
 and a.camera_id = #{cameraId, jdbcType=BIGINT}
 and a.preset_num like concat('%',#{presetNum, jdbcType=INTEGER},'%')
 and a.preset_name like concat('%',#{presetName, jdbcType=VARCHAR},'%')
 and a.creator_user = #{creatorUser, jdbcType=VARCHAR}
 and a.creator_time = #{creatorTime, jdbcType=TIMESTAMP}
 and a.is_use = #{isUse, jdbcType=INTEGER}
 and a.preset_img = #{presetImg, jdbcType=VARCHAR}
 and a.inspection_postion = #{inspectionPostion, jdbcType=INTEGER}
 and a.collect_status = #{collectStatus, jdbcType=INTEGER}
 and a.calibration_status = #{calibrationStatus, jdbcType=INTEGER}
 and a.remark = #{remark, jdbcType=VARCHAR}
and a.camera_id = b.camera_id
ORDER BY a.preset_num asc

